-- V30 — Inbound/transfer/third-party/tanker step pages fire real transitions.
-- Same class of fix as the outbound manager pages + loading-progress: these
-- were kind:list pages whose buttons flipped gate_pass.status directly (a list
-- row-action can't carry the instanceId the engine needs), so the UI could not
-- advance the workflow even though the engine could. Rebuilt as Forms with a GP
-- picker + WorkflowActionButtons that submit the guard values via submitValues:
--   gate-pass-closure   closure for ThirdPartyIn/IntTransferIn/PackUnload/
--                       ReturnStockIn (unguarded) + TankerInbound (tolerance)
--   dispatch-load-entry ThirdPartyOut / IntTransferOut load entry
--   qc-final-out        TankerOutbound final QC sample (APPROVED/REJECTED)
--   reconciliation      TankerInbound unload reconciliation (within/over)
-- Verified: all 11 M10 workflows still walk end-to-end to a terminal state.
-- Idempotent; bodies served live so this backfills fresh DBs.
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Gate Pass Closure", "span": 12, "subtitle": "Pick the gate pass ready to close. For a tanker recheck, the weight must be within tolerance to close; otherwise report the difference to the manager.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "flow_variant_code": "flow_variant_code"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "closure_note", "label": "Closure note (optional)", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Close Gate Pass", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "primary", "submitValues": {"withinTolerance": "YES", "weighment_verified": "OK", "seal_verified": "MATCHED", "invoice_count_verified": "YES"}}, {"kind": "WorkflowActionButton", "label": "⚠ Report Weight Difference", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "error", "submitValues": {"withinTolerance": "NO"}}]}]}]}]}'
WHERE pd.code='aria:gate-pass-closure' AND pv.body_json NOT LIKE '%submitValues%' AND pv.body_json NOT LIKE '%"scannable"%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Dispatch — Load Entry", "span": 12, "subtitle": "Pick the created gate pass and proceed to load entry.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "flow_variant_code": "flow_variant_code"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "load_note", "label": "Load note (optional)", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "▶ Proceed to Load Entry", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "primary", "submitValues": {}}]}]}]}]}'
WHERE pd.code='aria:dispatch-load-entry' AND pv.body_json NOT LIKE '%submitValues%' AND pv.body_json NOT LIKE '%"scannable"%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "QC — Final Outbound Sample", "span": 12, "subtitle": "Final QC on the loaded tanker sample before dispatch. Pass releases the vehicle; reject sends it back.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "flow_variant_code": "flow_variant_code"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "qc_notes", "label": "QC notes", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ QC Pass", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "primary", "submitValues": {"status": "APPROVED"}}, {"kind": "WorkflowActionButton", "label": "✗ QC Reject", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "error", "submitValues": {"status": "REJECTED"}}]}]}]}]}'
WHERE pd.code='aria:qc-final-out' AND pv.body_json NOT LIKE '%submitValues%' AND pv.body_json NOT LIKE '%"scannable"%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Unload Reconciliation", "span": 12, "subtitle": "Reconcile the unloaded quantity against the order. Within tolerance proceeds; a difference goes to the manager.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "flow_variant_code": "flow_variant_code"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "variance_reason", "label": "Variance reason (if any)", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Reconciled — Within Tolerance", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "primary", "submitValues": {"withinTolerance": "YES"}}, {"kind": "WorkflowActionButton", "label": "⚠ Difference → Manager", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "error", "submitValues": {"withinTolerance": "NO"}}]}]}]}]}'
WHERE pd.code='aria:reconciliation' AND pv.body_json NOT LIKE '%submitValues%' AND pv.body_json NOT LIKE '%"scannable"%';
